import{_ as n,l as o,o as e,c as l,v as t,p,x as r,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"BGP 收敛与抖动抑制","description":"","frontmatter":{"title":"BGP 收敛与抖动抑制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-convergence-dampening.md","filePath":"cs/bgp-convergence-dampening.md","lastUpdated":1789023840000}'),P={name:"cs/bgp-convergence-dampening.md"};function h(A,a,E,m,B,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="bgp-收敛与抖动抑制" tabindex="-1">BGP 收敛与抖动抑制 <a class="header-anchor" href="#bgp-收敛与抖动抑制" aria-label="Permalink to &quot;BGP 收敛与抖动抑制&quot;">​</a></h1><div class="epigraph"><p>路径向量的撤回要沿图扩散，最坏可经指数条交错路径；抖动抑制给反复上下的前缀记分关小黑屋，换稳定，也换长时间黑洞。</p><footer>—— 据 Labovitz et al., SIGCOMM 2000 延迟收敛；RFC 2439 路由抖动抑制整理</footer></div><p><a href="/cs/ibgp-route-reflector">上一课</a> 让全 AS 看见前缀。缺口是<strong>收敛要多久、抖动怎么办</strong>：MRAI 最小通告间隔、路径探索、dampening。本课不把 RPKI 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IGP 增量 SPF 常在亚秒到秒。BGP：一条前缀的最佳路径没了，要试次优，次优也可能正被别人撤回，形成路径探索。Labovitz 等测量到分钟级延迟。MRAI 限制通告频率，减负荷也拖收敛。Dampening：前缀在惩罚分超过阈则抑制，半衰期后才用——对不稳定客户有用，对被攻击或错误抑制的前缀是人为不可达。</p><p>不要把这当成 TCP 超时：控制面不可达与数据面 RTT 是两张表。</p><p><span class="marginnote">RFC 2439。许多运营商已关默认 dampening，因伤害无辜。本课钉机制与权衡，不下令。</span></p><h3 id="收敛以分钟为风险" tabindex="-1">收敛以分钟为风险 <a class="header-anchor" href="#收敛以分钟为风险" aria-label="Permalink to &quot;收敛以分钟为风险&quot;">​</a></h3><p>路径探索加 MRAI，不像增量 SPF。抑制稳表也可能长时间藏前缀。应用要多宿主，不把 SLA 绑在全球一致。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：撤回 → 探索次优 → MRAI 等待 → 新通告。对照 RIP 计数到无穷：都是向量收敛慢，BGP 因政策图更不规则。卫星链路的长 RTT 再叠 MRAI，会话保活也要调。</p>',11)),(e(),p(c,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WDR%5B%22%E6%92%A4%E5%9B%9E%22%5D%20--%3E%20EXP%5B%22%E8%B7%AF%E5%BE%84%E6%8E%A2%E7%B4%A2%22%5D%0A%20%20EXP%20--%3E%20MRAI%5B%22%E6%9C%80%E5%B0%8F%E9%80%9A%E5%91%8A%E9%97%B4%E9%9A%94%22%5D%0A%20%20FLAP%5B%22%E5%8F%8D%E5%A4%8D%E9%80%9A%E5%91%8A%22%5D%20--%3E%20PEN%5B%22%E6%83%A9%E7%BD%9A%E5%88%86%22%5D%0A%20%20PEN%20--%3E%20SUP%5B%22%E6%8A%91%E5%88%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RR 减少会话数，不保证更快的全球收敛：探索发生在 AS 之间。FIB 安装还有硬件延迟。与 RSTP 秒级对照：二层树小，BGP 图是互联网。端到端：应用超时往往先于 BGP 收敛，故要用多宿主与本地备选，而不是指望全球立刻一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BGP PIC 的全部预计算。BGP 劫持与 RPKI 是下一课。后课默认：BGP 收敛以分钟为量级风险；dampening 是双刃。</p><p>测量「已收敛」要用控制面与数据面两台尺子。</p><p>上一课留下的缺口在本课收口；「BGP 收敛与抖动抑制」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bgp-hijack-rpki">BGP 劫持与 RPKI</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路径探索 + MRAI 使 BGP 收敛远慢于 IGP。</li><li>抖动抑制稳表，也可能长时间藏前缀。</li><li>应用应多宿主，不把 SLA 绑在全球收敛上。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Labovitz et al., 2000；RFC 2439。</li></ul>',9))])}const u=n(P,[["render",h]]);export{b as __pageData,u as default};
